def write_dl(
    self,
    rows: cabc.Iterable[tuple[str, str]],
    col_max: int = 30,
    col_spacing: int = 2,
) -> None:
    rows = list(rows)
    widths = measure_table(rows)
    if len(widths) != 2:
        raise TypeError("Expected two columns for definition list")

    first_col = min(widths[0], col_max) + col_spacing

    for first, second in iter_rows(rows, len(widths)):
        self.write(f"{'':>{self.current_indent}}{first}")
        if not second:
            self.write("\n")
            continue
        if term_len(first) <= first_col - col_spacing:
            self.write(" " * (first_col - term_len(first)))
        else:
            self.write("\n")
            self.write(" " * (first_col + self.current_indent))

        text_width = max(self.width - first_col - 2, 10)
        wrapped_text = wrap_text(second, text_width, preserve_paragraphs=True)
        lines = wrapped_text.splitlines()

        if lines:
            self.write(f"{lines[0]}\n")

            for line in lines[1:]:
                self.write(f"{'':>{first_col + self.current_indent}}{line}\n")
        else:
            self.write("\n")

def lookup_default(self, name: str, call: bool = True) -> t.Any | None:
    if not self._default_map_has(name):
        return None

    # Assert to make the type checker happy.
    assert self.default_map is not None
    value = self.default_map[name]

    if call and callable(value):
        return value()

    return value

