def open_file(
    filename: str | os.PathLike[str],
    mode: str = "r",
    encoding: str | None = None,
    errors: str | None = "strict",
    lazy: bool = False,
    atomic: bool = False,
) -> t.IO[t.Any]:
    if lazy:
        return t.cast(
            "t.IO[t.Any]", _LazyFile(filename, mode, encoding, errors, atomic=atomic)
