    return formatter.getvalue().rstrip("\n")

def clear() -> None:
    if not isatty(sys.stdout):
        return

    # ANSI escape \033[2J clears the screen, \033[1;1H moves the cursor
    echo("\033[2J\033[1;1H", nl=False)

def launch(url: str, wait: bool = False, locate: bool = False) -> int:
    from ._termui_impl import open_url

    return open_url(url, wait=wait, locate=locate)

def make_parser(self, ctx: Context) -> _OptionParser:
    parser = _OptionParser(ctx)
    for param in self.get_params(ctx):
        param.add_to_parser(parser, ctx)
    return parser

def get_help_spec(self, ctx: Context) -> str:
    any_prefix_is_slash = False

    def _write_opts(opts: cabc.Sequence[str]) -> str:
        nonlocal any_prefix_is_slash

        rv, any_slashes = join_options(opts)

        if any_slashes:
            any_prefix_is_slash = True

        if not self.is_flag and not self.count:
            rv += f" {self.make_metavar(ctx=ctx)}"

        return rv

    rv = [_write_opts(self.opts)]

    if self.secondary_opts:
        rv.append(_write_opts(self.secondary_opts))

    return ("; " if any_prefix_is_slash else " / ").join(rv)

def shell_complete(self, ctx: Context, incomplete: str) -> list[CompletionItem]:
    if self._custom_shell_complete is not None:
        results = self._custom_shell_complete(ctx, self, incomplete)

        if results and isinstance(results[0], str):
            from click.shell_completion import CompletionItem

            results = [CompletionItem(c) for c in results]

        return t.cast("list[CompletionItem]", results)

    return self.type.shell_complete(ctx, self, incomplete)

def get_current_context(silent: bool = False) -> Context | None:
    try:
        return t.cast("Context", _local.stack[-1])
    except (AttributeError, IndexError) as e:
        if not silent:
            raise RuntimeError("There is no active click context.") from e

    return None

def make_pass_decorator(
    object_type: type[T], ensure: bool = False
) -> t.Callable[[t.Callable[te.Concatenate[T, P], R]], t.Callable[P, R]]:

    def decorator(f: t.Callable[te.Concatenate[T, P], R]) -> t.Callable[P, R]:
        def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
            ctx = get_current_context()

            obj: T | None
            if ensure:
                obj = ctx.ensure_object(object_type)
            else:
                obj = ctx.find_object(object_type)

            if obj is None:
                raise RuntimeError(
                    "Managed to invoke callback without a context"
                    f" object of type {object_type.__name__!r}"
                    " existing."
                )

            return ctx.invoke(f, obj, *args, **kwargs)

        return update_wrapper(new_func, f)

    return decorator

def shell_complete(
    self, ctx: Context, param: Parameter, incomplete: str
) -> list[CompletionItem]:
    return []

def exit(self, code: int = 0) -> t.NoReturn:
    self.close()
    raise Exit(code)

def group(
    name: str | _AnyCallable | None = None,
    cls: type[GrpType] | None = None,
    **attrs: t.Any,
) -> Group | t.Callable[[_AnyCallable], Group | GrpType]:
    if cls is None:
        cls = t.cast("type[GrpType]", Group)

    if callable(name):
        return command(cls=cls, **attrs)(name)

    return command(name, cls, **attrs)

def type_cast_value(self, ctx: Context, value: t.Any) -> t.Any:
    if value is None:
        if self.multiple or self.nargs == -1:
            return ()
        else:
            return value

    def check_iter(value: t.Any) -> cabc.Iterator[t.Any]:
        try:
            return _check_iter(value)
        except TypeError:
            # This should only happen when passing in args manually,
            # the parser should construct an iterable when parsing
            # the command line.
            raise BadParameter(
                _("Value must be an iterable."), ctx=ctx, param=self
            ) from None

    # Define the conversion function based on nargs and type.

    if self.nargs == 1 or self.type.is_composite:

        def convert(value: t.Any) -> t.Any:
            return self.type(value, param=self, ctx=ctx)

    elif self.nargs == -1:

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            return tuple(self.type(x, self, ctx) for x in check_iter(value))

    else:  # nargs > 1

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            value = tuple(check_iter(value))

            if len(value) != self.nargs:
                raise BadParameter(
                    ngettext(
                        "Takes {nargs} values but 1 was given.",
                        "Takes {nargs} values but {len} were given.",
                        len(value),
                    ).format(nargs=self.nargs, len=len(value)),
                    ctx=ctx,
                    param=self,
                )

            return tuple(self.type(x, self, ctx) for x in value)

    if self.multiple:
        return tuple(convert(x) for x in check_iter(value))

    return convert(value)

def command_path(self) -> str:
    rv = ""
    if self.info_name is not None:
        rv = self.info_name
    if self.parent is not None:
        parent_command_path = [self.parent.command_path]

        if isinstance(self.parent.command, Command):
            for param in self.parent.command.get_params(self):
                parent_command_path.extend(param.get_usage_pieces(self))

        rv = f"{' '.join(parent_command_path)} {rv}"
    return rv.lstrip()

def forward(self, cmd: Command, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
    # Can only forward to other commands, not direct callbacks.
    if not isinstance(cmd, Command):
        raise TypeError("Callback is not a command.")

    for param in self.params:
        if param not in kwargs:
            kwargs[param] = self.params[param]

    return self.invoke(cmd, *args, **kwargs)

def custom_version_option(
    callback: t.Callable[[Context], str],
    *param_decls: str,
    **kwargs: t.Any,
) -> t.Callable[[FC], FC]:

    def show_version(ctx: Context, param: Parameter, value: bool) -> None:
        if not value or ctx.resilient_parsing:
            return

        echo(callback(ctx), color=ctx.color)
        ctx.exit()

    if not param_decls:
        param_decls = ("--version",)

    kwargs.setdefault("is_flag", True)
    kwargs.setdefault("expose_value", False)
    kwargs.setdefault("is_eager", True)
    kwargs.setdefault("help", _("Show the version and exit."))
    kwargs["callback"] = show_version
    return option(*param_decls, **kwargs)

def fileno(self) -> int:
    if self._original_fd >= 0:
        return self._original_fd
    return super().fileno()

def value_from_envvar(self, ctx: Context) -> str | cabc.Sequence[str] | None:
    rv = self.resolve_envvar_value(ctx)

    if rv is not None and self.nargs != 1:
        return self.type.split_envvar_value(rv)

    return rv

def make_formatter(self) -> HelpFormatter:
    return self.formatter_class(
        width=self.terminal_width, max_width=self.max_content_width
    )

def invoke(
    self, callback: Command | t.Callable[..., V], /, *args: t.Any, **kwargs: t.Any
) -> t.Any | V:
    if isinstance(callback, Command):
        other_cmd = callback

        if other_cmd.callback is None:
            raise TypeError(
                "The given command does not have a callback that can be invoked."
            )
        else:
            callback = t.cast("t.Callable[..., V]", other_cmd.callback)

        ctx = self._make_sub_context(other_cmd)

        for param in other_cmd.params:
            if param.name not in kwargs and param.expose_value:
                default_value = param.get_default(ctx)
                # We explicitly hide the :attr:`UNSET` value to the user, as we
                # choose to make it an implementation detail. And because ``invoke``
                # has been designed as part of Click public API, we return ``None``
                # instead. Refs:
                # https://github.com/pallets/click/issues/3066
                # https://github.com/pallets/click/issues/3065
                # https://github.com/pallets/click/pull/3068
                if default_value is UNSET:
                    default_value = None
                kwargs[param.name] = param.type_cast_value(ctx, default_value)

        # Track all kwargs as params, so that forward() will pass
        # them on in subsequent calls.
        ctx.params.update(kwargs)
    else:
        ctx = self

    with augment_usage_errors(self), ctx:
        return callback(*args, **kwargs)

def shell_complete(self, ctx: Context, incomplete: str) -> list[CompletionItem]:
    from click.shell_completion import CompletionItem

    results = [
        CompletionItem(name, help=command.get_short_help_str())
        for name, command in _complete_visible_commands(ctx, incomplete)
    ]
    results.extend(super().shell_complete(ctx, incomplete))
    return results

def get_error_hint(self, ctx: Context | None) -> str:
    hint_list = self.opts or [self.spec]
    return " / ".join(f"'{x}'" for x in hint_list)

def resolve_color_default(color: bool | None = None) -> bool | None:
    if color is not None:
        return color

    ctx = get_current_context(silent=True)

    if ctx is not None:
        return ctx.color

    return None

def shell_complete(self, ctx: Context, incomplete: str) -> list[CompletionItem]:
    from click.shell_completion import CompletionItem

    results: list[CompletionItem] = []

    if incomplete and not incomplete[0].isalnum():
        for param in self.get_params(ctx):
            if (
                not isinstance(param, Option)
                or param.hidden
                or (
                    not param.multiple
                    and ctx.get_parameter_source(param.name)
                    is ParameterSource.COMMANDLINE
                )
            ):
                continue

            results.extend(
                CompletionItem(name, help=param.help)
                for name in [*param.opts, *param.secondary_opts]
                if name.startswith(incomplete)
            )

    while ctx.parent is not None:
        ctx = ctx.parent

        if isinstance(ctx.command, Group) and ctx.command.chain:
            results.extend(
                CompletionItem(name, help=command.get_short_help_str())
                for name, command in _complete_visible_commands(ctx, incomplete)
                if name not in ctx._protected_args
            )

    return results

def shell_complete(
    cli: Command,
    ctx_args: cabc.MutableMapping[str, t.Any],
    prog_name: str,
    complete_var: str,
    instruction: str,
) -> t.Literal[0, 1]:
    shell, _, instruction = instruction.partition("_")
    comp_cls = get_completion_class(shell)

    if comp_cls is None:
        return 1

    comp = comp_cls(cli, ctx_args, prog_name, complete_var)

    # Write bytes, otherwise Windows text stdout translates LF to CRLF and breaks.
    if instruction == "source":
        echo(comp.source().encode(), nl=False)
        return 0

    if instruction == "complete":
        echo(comp.complete().encode())
        return 0

    return 1

def pause(info: str | None = None, err: bool = False) -> None:
    if not isatty(sys.stdin) or not isatty(sys.stdout):
        return

    if info is None:
        info = _("Press any key to continue...")

    try:
        if info:
            echo(info, nl=False, err=err)
        try:
            getchar()
        except (KeyboardInterrupt, EOFError):
            pass
    finally:
        if info:
            echo(err=err)

def get_short_help_str(self, limit: int = 45) -> str:
    if self.short_help:
        text = inspect.cleandoc(self.short_help)
    elif self.help:
        text = _make_default_short_help(self.help, limit)
    else:
        text = ""

    if self.deprecated:
        text = f"{_(text)} {_format_deprecated_label(self.deprecated)}"

    return text.strip()

def get_invalid_choice_message(self, value: t.Any, ctx: Context | None) -> str:
    choices_str = ", ".join(map(repr, self._normalized_mapping(ctx=ctx).values()))
    return ngettext(
        "{value!r} is not {choice}.",
        "{value!r} is not one of {choices}.",
        len(self.choices),
    ).format(value=value, choice=choices_str, choices=choices_str)

def prompt(
    text: str,
    default: V | str | None = None,
    hide_input: bool = False,
    confirmation_prompt: bool | str = False,
    type: ParamType[V, str] | type[V] | None = None,
    value_proc: t.Callable[[str], V] | None = None,
    prompt_suffix: str = ": ",
    show_default: bool | str = True,
    err: bool = False,
    show_choices: bool = True,
) -> V:

    def prompt_func(text: str) -> str:
        f = hidden_prompt_func if hide_input else visible_prompt_func
        try:
            return _readline_prompt(f, text, err)
        except (KeyboardInterrupt, EOFError):
            # getpass doesn't print a newline if the user aborts input with ^C.
            # Allegedly this behavior is inherited from getpass(3).
            # A doc bug has been filed at https://bugs.python.org/issue24711
            if hide_input:
                echo(None, err=err)
            raise Abort() from None

    if value_proc is None:
        value_proc = convert_type(type, default)

    prompt = _build_prompt(
        text, prompt_suffix, show_default, default, show_choices, type
    )

    if confirmation_prompt:
        if confirmation_prompt is True:
            confirmation_prompt = _("Repeat for confirmation")

        confirmation_prompt = _build_prompt(confirmation_prompt, prompt_suffix)

    while True:
        while True:
            value = prompt_func(prompt)
            if value:
                break
            elif default is not None:
                # Defaults of any type are accepted and round trip through
                # value_proc like typed input, so the annotation is only
                # accurate for typed input.
                value = t.cast("str", default)
                break
        try:
            result = value_proc(value)
        except UsageError as e:
            message = _mask_hidden_input(e.message, value) if hide_input else e.message
            echo(_("Error: {message}").format(message=message), err=err)
            continue
        if not confirmation_prompt:
            return result
        while True:
            value2 = prompt_func(confirmation_prompt)
            is_empty = not value and not value2
            if value2 or is_empty:
                break
        if value == value2:
            return result
        echo(_("Error: The two entered values do not match."), err=err)

def get_usage(self, ctx: Context) -> str:
    formatter = ctx.make_formatter()
    self.format_usage(ctx, formatter)
    return formatter.getvalue().rstrip("\n")

def command(
    self, *args: t.Any, **kwargs: t.Any
) -> t.Callable[[t.Callable[..., t.Any]], Command] | Command:
    from .decorators import command

    func: t.Callable[..., t.Any] | None = None

    if args and callable(args[0]):
        assert len(args) == 1 and not kwargs, (
            "Use 'command(**kwargs)(callable)' to provide arguments."
        )
        (func,) = args
        args = ()

    if self.command_class and kwargs.get("cls") is None:
        kwargs["cls"] = self.command_class

    def decorator(f: t.Callable[..., t.Any]) -> Command:
        cmd: Command = command(*args, **kwargs)(f)
        self.add_command(cmd)
        return cmd

    if func is not None:
        return decorator(func)

    return decorator

def format_options(self, ctx: Context, formatter: HelpFormatter) -> None:
    opts = []
    for param in self.get_params(ctx):
        rv = param.get_help_record(ctx)
        if rv is not None and not isinstance(param, Argument):
            opts.append(rv)

    if opts:
        with formatter.section(_("Options")):
            formatter.write_dl(opts)

def augment_usage_errors(
    ctx: Context, param: Parameter | None = None
) -> cabc.Generator[None]:
    try:
        yield
    except BadParameter as e:
        if e.ctx is None:
            e.ctx = ctx
        if param is not None and e.param is None:
            e.param = param
        raise
    except UsageError as e:
        if e.ctx is None:
            e.ctx = ctx
        raise

def consume_value(
    self, ctx: Context, opts: cabc.Mapping[str, t.Any]
) -> tuple[t.Any, ParameterSource]:
    # Collect from the parse the value passed by the user to the CLI.
    value = opts.get(self.name, UNSET)
    # If the value is set, it means it was sourced from the command line by the
    # parser, otherwise it left unset by default.
    source = (
        ParameterSource.COMMANDLINE
        if value is not UNSET
        else ParameterSource.DEFAULT
    )

    if value is UNSET:
        envvar_value = self.value_from_envvar(ctx)
        if envvar_value is not None:
            value = envvar_value
            source = ParameterSource.ENVIRONMENT

    if value is UNSET:
        default_map_value = ctx.lookup_default(self.name)
        if default_map_value is not None or ctx._default_map_has(self.name):
            value = default_map_value
            source = ParameterSource.DEFAULT_MAP

            # A string from default_map must be split for multi-value
            # parameters, matching value_from_envvar behavior.
            if isinstance(value, str) and self.nargs != 1:
                value = self.type.split_envvar_value(value)

    if value is UNSET:
        default_value = self.get_default(ctx)
        if default_value is not UNSET:
            value = default_value
            source = ParameterSource.DEFAULT

    return value, source

def option(
    *param_decls: str, cls: type[Option] | None = None, **attrs: t.Any
) -> t.Callable[[FC], FC]:
    if cls is None:
        cls = Option

    def decorator(f: FC) -> FC:
        _param_memo(f, cls(param_decls, **attrs))
        return f

    return decorator

def add_command(self, cmd: Command, name: str | None = None) -> None:
    name = name or cmd.name
    if name is None:
        raise TypeError("Command has no name.")
    _check_nested_chain(self, name, cmd, register=True)
    self.commands[name] = cmd

def shell_complete(
    self, ctx: Context, param: Parameter, incomplete: str
) -> list[CompletionItem]:
    from click.shell_completion import CompletionItem

    type = "dir" if self.dir_okay and not self.file_okay else "file"
    return [CompletionItem(incomplete, type=type)]

def format_commands(self, ctx: Context, formatter: HelpFormatter) -> None:
    commands = []
    for subcommand in self.list_commands(ctx):
        cmd = self.get_command(ctx, subcommand)
        # What is this, the tool lied about a command.  Ignore it
        if cmd is None:
            continue
        if cmd.hidden:
            continue

        commands.append((subcommand, cmd))

    # allow for 3 times the default spacing
    if len(commands):
        limit = formatter.width - 6 - max(len(cmd[0]) for cmd in commands)

        rows = []
        for subcommand, cmd in commands:
            help = cmd.get_short_help_str(limit)
            rows.append((subcommand, help))

        if rows:
            with formatter.section(_("Commands")):
                formatter.write_dl(rows)

def getchar(echo: bool = False) -> str:
    global _getchar

    if _getchar is None:
        from ._termui_impl import getchar as f

        _getchar = f

    return _getchar(echo)

def group(
    self, *args: t.Any, **kwargs: t.Any
) -> t.Callable[[t.Callable[..., t.Any]], Group] | Group:
    from .decorators import group

    func: t.Callable[..., t.Any] | None = None

    if args and callable(args[0]):
        assert len(args) == 1 and not kwargs, (
            "Use 'group(**kwargs)(callable)' to provide arguments."
        )
        (func,) = args
        args = ()

    if self.group_class is not None and kwargs.get("cls") is None:
        if self.group_class is type:
            kwargs["cls"] = type(self)
        else:
            kwargs["cls"] = self.group_class

    def decorator(f: t.Callable[..., t.Any]) -> Group:
        cmd: Group = group(*args, **kwargs)(f)
        self.add_command(cmd)
        return cmd

    if func is not None:
        return decorator(func)

    return decorator

def confirmation_option(*param_decls: str, **kwargs: t.Any) -> t.Callable[[FC], FC]:

    def callback(ctx: Context, param: Parameter, value: bool) -> None:
        if not value:
            ctx.abort()

    if not param_decls:
        param_decls = ("--yes",)

    kwargs.setdefault("is_flag", True)
    kwargs.setdefault("callback", callback)
    kwargs.setdefault("expose_value", False)
    kwargs.setdefault("prompt", _("Do you want to continue?"))
    kwargs.setdefault("help", _("Confirm the action without prompting."))
    return option(*param_decls, **kwargs)

def result_callback(self, replace: bool = False) -> t.Callable[[F], F]:

    def decorator(f: F) -> F:
        old_callback = self._result_callback

        if old_callback is None or replace:
            self._result_callback = f
            return f

        def function(value: t.Any, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
            inner = old_callback(value, *args, **kwargs)
            return f(inner, *args, **kwargs)

        self._result_callback = rv = update_wrapper(t.cast(F, function), f)
        return rv  # type: ignore[return-value]

    return decorator

def get_app_dir(app_name: str, roaming: bool = True, force_posix: bool = False) -> str:
    if WIN:
        key = "APPDATA" if roaming else "LOCALAPPDATA"
        folder = os.environ.get(key)
        if folder is None:
            folder = os.path.expanduser("~")
        return os.path.join(folder, app_name)
    if force_posix:
        return os.path.join(os.path.expanduser(f"~/.{_posixify(app_name)}"))
    if sys.platform == "darwin":
        return os.path.join(
            os.path.expanduser("~/Library/Application Support"), app_name
        )
    return os.path.join(
        os.environ.get("XDG_CONFIG_HOME", os.path.expanduser("~/.config")),
        _posixify(app_name),
    )

def version_option(
    version: str | None = None,
    *param_decls: str,
    package_name: str | None = None,
    prog_name: str | None = None,
    message: str | None = None,
    **kwargs: t.Any,
) -> t.Callable[[FC], FC]:
    if message is None:
        message = _("%(prog)s, version %(version)s")

    if version is None and package_name is None:
        frame = inspect.currentframe()
        f_back = frame.f_back if frame is not None else None
        f_globals = f_back.f_globals if f_back is not None else None
        # break reference cycle
        # https://docs.python.org/3/library/inspect.html#the-interpreter-stack
        del frame

        if f_globals is not None:
            package_name = f_globals.get("__name__")

            if package_name == "__main__":
                package_name = f_globals.get("__package__")

            if package_name:
                package_name = package_name.partition(".")[0]

    def callback(ctx: Context, param: Parameter, value: bool) -> None:
        if not value or ctx.resilient_parsing:
            return

        nonlocal prog_name
        nonlocal version
        nonlocal package_name

        if prog_name is None:
            prog_name = ctx.find_root().info_name

        if version is None and package_name is not None:
            import importlib.metadata

            try:
                version = importlib.metadata.version(package_name)
            except importlib.metadata.PackageNotFoundError:
                # The given name didn't match an installed distribution.
                # Try resolving it as an import (top-level module) name,
                # e.g. ``PIL`` is provided by the ``Pillow`` distribution.
                distributions = importlib.metadata.packages_distributions().get(
                    package_name, []
                )
                if len(distributions) == 1:
                    package_name = distributions[0]
                    version = importlib.metadata.version(package_name)
                elif len(distributions) > 1:
                    raise RuntimeError(
                        f"{package_name!r} maps to multiple installed"
                        f" distributions ({', '.join(distributions)})."
                        " Pass 'package_name' to disambiguate."
                    ) from None
                else:
                    raise RuntimeError(
                        f"{package_name!r} is not installed. Try passing"
                        " 'package_name' instead."
                    ) from None

        if version is None:
            raise RuntimeError(
                f"Could not determine the version for {package_name!r} automatically."
            )

        echo(
            message % {"prog": prog_name, "package": package_name, "version": version},
            color=ctx.color,
        )
        ctx.exit()

    if not param_decls:
        param_decls = ("--version",)

    kwargs.setdefault("is_flag", True)
    kwargs.setdefault("expose_value", False)
    kwargs.setdefault("is_eager", True)
    kwargs.setdefault("help", _("Show the version and exit."))
    kwargs["callback"] = callback
    return option(*param_decls, **kwargs)

def password_option(*param_decls: str, **kwargs: t.Any) -> t.Callable[[FC], FC]:
    if not param_decls:
        param_decls = ("--password",)

    kwargs.setdefault("prompt", True)
    kwargs.setdefault("confirmation_prompt", True)
    kwargs.setdefault("hide_input", True)
    return option(*param_decls, **kwargs)
